-- ÜRETİLDİ, elle düzenlemeyin
/* ==========================================================================
   T07 — KVKK metin sürümleri

   Üreten: tools/vt/tohum-uret.mjs (npm run vt -- tohum). Bu dosyayı elle
   düzenlemeyin: kaynak değişince yeniden üretilir ve el değişikliği
   kaybolur. Kaynağı değiştirin, sonra "npm run vt -- tohum" çalıştırın.

   6 metin satırı (sürüm 1.1, 2026-09-29).

   Kaynak: src/data/kvkk.js (METINLER, KVKK_SURUM, KVKK_TARIH), src/data/kvkk.en.js
   (metinDilde ile). IcerikJson: metnin başlık dışındaki bölümleri, şirket
   bilgileri yerleşmiş hâliyle; IcerikOzeti: o JSON metninin UTF-8 SHA-256 özeti.
   Tasarım: tasarim.md 5.2 T07.

   Yalnız ekleme: var olan sürümün içeriği değişmişse betik durur (sürümü
   artırın). MERGE yazılmaz: kvkk.MetinSurumu INSTEAD OF tetikleyicilidir.
   Hukuk onayı kaynakta yok; HukukOnayiZamani boş kalır.

   Araç betiği tek işlemde, sahip girişiyle çalıştırır (BEGIN/COMMIT
   burada yazılmaz). İkinci çalıştırmada hiçbir satır değişmez.
   ========================================================================== */

/* kvkk.MetinSurumu — aynı sürüm numarasıyla farklı içerik: dur */
IF EXISTS (
    SELECT 1
    FROM kvkk.MetinSurumu AS h
    JOIN (VALUES
        (N'acikRiza', N'1.1', N'en', 0x794375BAC6BE9177D39D3923C28208FFB02419A2F4716E719816EB11BC16104A),
        (N'acikRiza', N'1.1', N'tr', 0xE59E806E522A284AE57017C208F2B138FB284FEB8B6E8EE78BE2704E45626D8E),
        (N'aydinlatma', N'1.1', N'en', 0x71A3552F3ECD3FBF5061F805245E697B03CC6DDD1E9FBE0F06F417BEB1A2CE46),
        (N'aydinlatma', N'1.1', N'tr', 0xB950E88D2FF052FD17ACF47D72FCCBD8F84578D01D45FC44095683DECB4E48C3),
        (N'ticariIleti', N'1.1', N'en', 0xEB29354220B706D56C7A3B51FC1C93C1A1C29C10AA6B1221F162EE9A3DC57D7D),
        (N'ticariIleti', N'1.1', N'tr', 0x3239D114E858C95E2936356398955181ACCDA55DFBE0EEBD1ADC424C64F7C891)
    ) AS k (MetinKodu, Surum, DilKodu, IcerikOzeti)
      ON h.MetinKodu = k.MetinKodu AND h.Surum = k.Surum AND h.DilKodu = k.DilKodu
    WHERE h.IcerikOzeti <> CONVERT(binary(32), k.IcerikOzeti)
)
    THROW 50003, N'kişisel verilerin korunması metninin içeriği değişmiş ancak sürüm numarası aynı; src/data/kvkk.js içindeki KVKK_SURUM değerini artırın.', 1;

/* kvkk.MetinSurumu — 6 satır, yalnız eksikler eklenir */

INSERT INTO kvkk.MetinSurumu (MetinKodu, Surum, DilKodu, Baslik, IcerikJson, IcerikOzeti, AsilMetin, MetinTarihi)
SELECT k.MetinKodu, k.Surum, k.DilKodu, k.Baslik, k.IcerikJson, k.IcerikOzeti, k.AsilMetin, k.MetinTarihi
FROM (
    SELECT CONVERT(nvarchar(40), v.MetinKodu) AS MetinKodu,
           CONVERT(nvarchar(10), v.Surum) AS Surum,
           CONVERT(nvarchar(5), v.DilKodu) AS DilKodu,
           CONVERT(nvarchar(200), v.Baslik) AS Baslik,
           CONVERT(nvarchar(max), v.IcerikJson) AS IcerikJson,
           CONVERT(binary(32), v.IcerikOzeti) AS IcerikOzeti,
           CONVERT(bit, v.AsilMetin) AS AsilMetin,
           CONVERT(date, v.MetinTarihi) AS MetinTarihi
    FROM (VALUES
        (N'acikRiza', N'1.1', N'en', N'Explicit Consent Text', N'{"kisaAd":"Explicit Consent Text","onayCumlesi":"I have read the Explicit Consent Text; I give my explicit consent to the processing of my personal data as described in it and to its transfer to the authorised service and dealer.","bolumler":[{"baslik":"What are you consenting to?","paragraflar":["I have also read the Privacy Notice. I give my explicit consent to PAKSAN MAKİNA SANAYİ VE TİCARET A.Ş. processing my first and last name, mobile phone number, province and district, details of the machine I registered and the content of my requests in order to run after-sales support, service, spare part and warranty processes."]},{"baslik":"Sharing with the service and dealer","paragraflar":["When I create a service request, I give my explicit consent to my first and last name, phone number, the address where my machine is located, my machine''s details and the content of my request (including photos, videos and voice recordings) being transferred to the authorised service assigned to my machine or handling my request. When I create a quotation request, I give my explicit consent to my first and last name, phone number, province and the content of my request being transferred to the authorised dealer that will answer it."]},{"baslik":"Contacting you","paragraflar":["I consent to PAKSAN or the authorised service handling my request contacting me by phone, SMS and app notification about the requests I create.","This contact covers only service matters such as confirming that my request was received, service appointments and safety warnings about my machine. Campaign and announcement notifications are not included; they need separate permission."]},{"baslik":"You can withdraw your consent","paragraflar":["You can withdraw this consent at any time through the application channels in the Privacy Notice or by writing to paksan@paksanmakina.com.tr. Processing carried out before you withdraw remains valid. When you withdraw your consent your requests can no longer be passed to the service, so you may not be able to keep using the app. In that case we will contact you to close your account."]}],"ustNot":"This is an English translation provided for convenience. The binding text is the Turkish original, prepared under Turkish Personal Data Protection Law No. 6698 (KVKK)."}', 0x794375BAC6BE9177D39D3923C28208FFB02419A2F4716E719816EB11BC16104A, 0, N'2026-09-29'),
        (N'acikRiza', N'1.1', N'tr', N'Açık Rıza Metni', N'{"kisaAd":"Açık Rıza Metni","onayCumlesi":"Açık Rıza Metni’ni okudum; kişisel verilerimin bu metinde belirtilen şekilde işlenmesine ve yetkili servis ile bayiye aktarılmasına açık rıza veriyorum.","bolumler":[{"baslik":"Neye rıza veriyorsunuz?","paragraflar":["Aydınlatma Metni’ni ayrıca okudum. Adımın ve soyadımın, cep telefonu numaramın, il ve ilçe bilgilerimin, kaydettiğim makineye ait bilgilerin ve oluşturduğum taleplerin içeriğinin PAKSAN MAKİNA SANAYİ VE TİCARET A.Ş. tarafından satış sonrası destek, servis, yedek parça ve garanti süreçlerinin yürütülmesi amacıyla işlenmesine açık rıza veriyorum."]},{"baslik":"Servis ve bayiye aktarım","paragraflar":["Servis talebi oluşturduğumda adımın ve soyadımın, telefon numaramın, makinemin bulunduğu adresin, makineme ait bilgilerin ve talebimin içeriğinin (fotoğraf, video ve ses kayıtları dâhil) makineme atanmış ya da talebimi yürüten yetkili servise aktarılmasına açık rıza veriyorum. Fiyat teklifi talebi oluşturduğumda adımın ve soyadımın, telefon numaramın, il bilgimin ve talebimin içeriğinin talebi karşılayacak yetkili bayiye aktarılmasına açık rıza veriyorum."]},{"baslik":"Sizinle iletişim","paragraflar":["Oluşturduğum taleplerle ilgili olarak PAKSAN’ın ya da talebimi yürüten yetkili servisin telefon, SMS ve uygulama bildirimi yoluyla benimle iletişime geçmesine rıza veriyorum.","Bu iletişim yalnızca talebimin alındığının bildirilmesi, servis randevusu ve makinemle ilgili güvenlik uyarıları gibi hizmete ilişkin konuları kapsar. Kampanya ve duyuru bildirimleri bu kapsama girmez; bunlar için ayrıca izin verilmesi gerekir."]},{"baslik":"Rızanızı geri alabilirsiniz","paragraflar":["Bu rızayı dilediğiniz zaman Aydınlatma Metni’nde belirtilen başvuru yollarıyla ya da paksan@paksanmakina.com.tr adresine yazarak geri alabilirsiniz. Rızanızı geri almadan önce yapılan işlemler geçerliliğini korur. Rızanızı geri aldığınızda talepleriniz servise iletilemeyeceği için uygulamayı kullanmaya devam edemeyebilirsiniz. Bu durumda hesabınızın kapatılması için sizinle iletişime geçeriz."]}]}', 0xE59E806E522A284AE57017C208F2B138FB284FEB8B6E8EE78BE2704E45626D8E, 1, N'2026-09-29'),
        (N'aydinlatma', N'1.1', N'en', N'Privacy Notice', N'{"kisaAd":"Privacy Notice","onayCumlesi":"I have read and understood the Privacy Notice.","bolumler":[{"baslik":"Who is the data controller?","paragraflar":["Your personal data is processed by the data controller PAKSAN MAKİNA SANAYİ VE TİCARET A.Ş. as described in this notice, under Turkish Personal Data Protection Law No. 6698 (KVKK).","Address: Bandırma – Bursa Karayolu 10. km, Bandırma / Balıkesir","Address: Taştepe, Deri Organize Sanayi Bölgesi, 10900 Gönen / Balıkesir","Telephone: 444 9 725 · +90 266 733 90 90 · Fax: +90 266 733 90 99","E-mail: paksan@paksanmakina.com.tr"]},{"baslik":"Which data is processed?","maddeler":["Identity and contact: your first name, last name and mobile phone number","Location: your province and district, the address where the machine is located (in a service request), the address a spare part is sent to","Machine: the serial number, model, production year and warranty status of the machine you registered, and the maintenance you ticked off","Requests: what you write in service, spare part and quotation requests; the photos, videos and voice recordings you attach; information you add later; appointments","Service records: the work the authorised service did on your machine, the parts it replaced and visit details","Invoice and payment: the name of the person or company to be invoiced, Turkish ID number or tax number, invoice and delivery address, the payment receipt you upload","Support use: the machine, section and symptom you choose on the Support screen and the checks you tick","Feedback and requests: feedback you send about the app and your phone number change application","Transaction security: an irreversible digest of your password, sign-in times and app version","Notifications: if you allow notifications, your device''s notification ID and permission status","Preferences: your campaign notification permission, language and appearance choice"]},{"baslik":"For what purpose and on what legal basis?","paragraflar":["Each purpose is followed by its legal basis under Article 5 of the KVKK:"],"maddeler":["Opening your account, signing you in and keeping your account secure — establishment and performance of a contract (Art. 5/2-c), legitimate interest (Art. 5/2-f)","Registering your machine and tracking its warranty — performance of a contract (Art. 5/2-c), legal obligation (Art. 5/2-ç)","Passing your service request to the authorised service looking after your machine, handling the appointment and service record — performance of a contract (Art. 5/2-c)","Invoicing your spare part order, verifying your payment and shipping the part — performance of a contract (Art. 5/2-c), legal obligation (Art. 5/2-ç)","Answering your quotation request — establishment of a contract (Art. 5/2-c)","Notifying you when the status of your request changes — performance of a contract (Art. 5/2-c)","Sending safety warnings about your machine — legal obligation (Art. 5/2-ç), legitimate interest (Art. 5/2-f)","Improving products and services using Support screen records — legitimate interest (Art. 5/2-f)","Protecting our rights in possible disputes and meeting requests from authorities — establishment, exercise or protection of a right (Art. 5/2-e), legal obligation (Art. 5/2-ç)","The processing described in the Explicit Consent Text — your explicit consent (Art. 5/1)","If you allow it, sending campaigns and announcements — your explicit consent and your consent to commercial electronic messages"]},{"baslik":"Who is it shared with?","paragraflar":["Your data is shared only as far as each purpose requires, with these recipients:"],"maddeler":["Authorised service: your name, phone number, the address where the machine is located, machine details, the content and attachments of your request are shared with the PAKSAN authorised service assigned to your machine or handling your request.","An authorised service opening a record for you: when an authorised service opens a record for you, it can find your account by your phone number or your machine''s serial number. In that case that service can see your name, province and registered machines.","Authorised dealer: for a quotation request, your name, phone number, province and the content of your request are shared with the authorised dealer that will answer it.","Cargo companies: for spare part shipping, the recipient''s name, delivery address and phone number are shared.","Service providers: shared with companies that work on behalf of and on the instructions of PAKSAN, such as the server hosting the app and the notification infrastructure.","Financial advisers, auditors and legal counsel: shared as far as the law requires.","Authorised public institutions: shared where the law requires."]},{"baslik":"Is it transferred abroad?","paragraflar":["Your personal data is not transferred abroad at present. If this changes, for example because of the notification infrastructure, this notice will be updated and the conditions of Article 9 of the KVKK will be met."]},{"baslik":"How is it collected?","paragraflar":["Your data is collected electronically in these ways:"],"maddeler":["What you write in the app and the photos, videos, voice recordings and receipts you upload","Records an authorised service opens for you and records of the work it does on your machine","Information you give PAKSAN by phone","Records the app creates automatically: sign-in times, app version and, if you allow notifications, your device''s notification ID","The app does not use your phone''s location; your location is only the province, district and address you write yourself."]},{"baslik":"How long is it kept?","paragraflar":["Your data is kept while your account is open. After your account is closed it is kept for the periods required by warranty, consumer, tax and commercial law and for the limitation periods of possible disputes. At the end of these periods it is deleted, destroyed or anonymised."]},{"baslik":"What are your rights?","paragraflar":["Under Article 11 of the KVKK you have the right to:"],"maddeler":["Learn whether your personal data is processed and, if so, request information about it","Learn the purpose of processing and whether it is used in line with that purpose","Know the third parties in Turkey or abroad your personal data is transferred to","Request correction if your personal data is incomplete or inaccurate","Request deletion or destruction of your personal data when the conditions are met","Request that corrections and deletions be notified to the third parties your data was transferred to","Object to a result against you arising solely from automated analysis of your personal data","Claim compensation if you suffer damage because your personal data was processed unlawfully"]},{"baslik":"How do you apply?","paragraflar":["You can send your application to our address above with a wet-signed letter. You can also apply by registered electronic mail (KEP), secure electronic signature or mobile signature, or by writing to paksan@paksanmakina.com.tr from an e-mail address you gave us earlier and that is registered in our system.","Your application must include your first and last name, Turkish ID number (for foreign nationals, nationality and passport number), address for notifications, e-mail address and phone number if any, and the subject of your request.","Your application is concluded free of charge within 30 days at the latest. If you are not satisfied with the answer you can complain to the Personal Data Protection Board.","You can request the closure of your account and deletion of your data in the same ways. PAKSAN carries this out. Records subject to a legal retention period (for example invoices) are kept until the end of that period; other records are deleted or anonymised.","The app is intended for users over 18."]}],"ustNot":"This is an English translation provided for convenience. The binding text is the Turkish original, prepared under Turkish Personal Data Protection Law No. 6698 (KVKK)."}', 0x71A3552F3ECD3FBF5061F805245E697B03CC6DDD1E9FBE0F06F417BEB1A2CE46, 0, N'2026-09-29'),
        (N'aydinlatma', N'1.1', N'tr', N'KVKK Aydınlatma Metni', N'{"kisaAd":"Aydınlatma Metni","onayCumlesi":"Aydınlatma Metni’ni okudum ve anladım.","bolumler":[{"baslik":"Veri sorumlusu kim?","paragraflar":["Kişisel verileriniz, 6698 sayılı Kişisel Verilerin Korunması Kanunu (KVKK) uyarınca veri sorumlusu PAKSAN MAKİNA SANAYİ VE TİCARET A.Ş. tarafından bu metinde açıklandığı şekilde işlenir.","Adres: Bandırma – Bursa Karayolu 10. km, Bandırma / Balıkesir","Adres: Taştepe, Deri Organize Sanayi Bölgesi, 10900 Gönen / Balıkesir","Telefon: 444 9 725 · +90 266 733 90 90 · Faks: +90 266 733 90 99","E-posta: paksan@paksanmakina.com.tr"]},{"baslik":"Hangi verileriniz işleniyor?","maddeler":["Kimlik ve iletişim: adınız, soyadınız ve cep telefonu numaranız","Konum: iliniz ve ilçeniz, servis talebinde belirttiğiniz makinenin bulunduğu adres, yedek parçanın gönderileceği adres","Makine: kaydettiğiniz makinenin seri numarası, modeli, üretim yılı, garanti durumu ve işaretlediğiniz bakımlar","Talepler: servis, yedek parça ve fiyat teklifi taleplerinizde yazdıklarınız; eklediğiniz fotoğraf, video ve ses kayıtları; sonradan eklediğiniz bilgiler; randevular","Servis kayıtları: yetkili servisin makinenizde yaptığı işlemler, değiştirdiği parçalar ve ziyaret bilgileri","Fatura ve ödeme: adına fatura düzenlenecek kişi ya da firmanın adı, T.C. kimlik numarası ya da vergi numarası, fatura ve teslimat adresi, yüklediğiniz ödeme dekontu","Destek kullanımı: Destek ekranında seçtiğiniz makine, bölüm ve belirti ile işaretlediğiniz kontroller","Görüş ve talepler: uygulama hakkında gönderdiğiniz görüşler ve telefon numarası değişikliği başvurunuz","İşlem güvenliği: şifrenizin geri döndürülemeyen özeti, giriş zamanları ve uygulama sürümü","Bildirim: bildirimlere izin verdiyseniz cihazınızın bildirim kimliği ve izin durumu","Tercihler: kampanya bildirimi izniniz, dil ve görünüm seçiminiz"]},{"baslik":"Hangi amaçla ve hangi hukuki sebeple işleniyor?","paragraflar":["Her amacın yanında KVKK’nın 5. maddesinde yer alan ilgili hukuki sebep belirtilmiştir:"],"maddeler":["Hesabınızı açmak, giriş yapmanızı sağlamak ve hesap güvenliğinizi korumak — sözleşmenin kurulması ve ifası (md. 5/2-c), meşru menfaat (md. 5/2-f)","Makinenizi kaydetmek ve garanti durumunu takip etmek — sözleşmenin ifası (md. 5/2-c), hukuki yükümlülük (md. 5/2-ç)","Servis talebinizi makinenizle ilgilenen yetkili servise iletmek, randevu ve servis kaydı işlemlerini yürütmek — sözleşmenin ifası (md. 5/2-c)","Yedek parça siparişinizin faturasını düzenlemek, ödemenizi doğrulamak ve parçayı göndermek — sözleşmenin ifası (md. 5/2-c), hukuki yükümlülük (md. 5/2-ç)","Fiyat teklifi talebinizi yanıtlamak — sözleşmenin kurulması (md. 5/2-c)","Talebinizin durumu değiştiğinde size bildirim göndermek — sözleşmenin ifası (md. 5/2-c)","Makinenizle ilgili güvenlik uyarılarını iletmek — hukuki yükümlülük (md. 5/2-ç), meşru menfaat (md. 5/2-f)","Destek ekranı kayıtlarından yararlanarak ürün ve hizmet kalitesini geliştirmek — meşru menfaat (md. 5/2-f)","Olası uyuşmazlıklarda haklarımızı korumak ve resmî makamların taleplerini karşılamak — bir hakkın tesisi, kullanılması veya korunması (md. 5/2-e), hukuki yükümlülük (md. 5/2-ç)","Açık Rıza Metni’nde belirtilen işlemleri yapmak — açık rızanız (md. 5/1)","İzin verirseniz kampanya ve duyuruları iletmek — açık rızanız ve ticari elektronik ileti onayınız"]},{"baslik":"Kimlere aktarılıyor?","paragraflar":["Verileriniz, yalnızca ilgili amacın gerektirdiği ölçüde şu alıcılara aktarılır:"],"maddeler":["Yetkili servis: adınız, telefon numaranız, makinenin bulunduğu adres, makine bilgileri, talebinizin içeriği ve ekleri, makinenize atanmış ya da talebinizi yürüten PAKSAN yetkili servisine aktarılır.","Yetkili servisin sizin için kayıt açması: yetkili bir servis, sizin için kayıt açarken telefon numaranız ya da makinenizin seri numarasıyla hesabınızı bulabilir. Bu durumda adınız, iliniz ve kayıtlı makineleriniz o servis tarafından görülebilir.","Yetkili bayi: fiyat teklifi talebiniz olduğunda adınız, telefon numaranız, iliniz ve talebinizin içeriği, talebi karşılayacak yetkili bayiye aktarılır.","Kargo şirketleri: yedek parça gönderimi için alıcının adı, teslimat adresi ve telefon numarası aktarılır.","Hizmet sağlayıcılar: uygulamanın barındırıldığı sunucu ve bildirim altyapısı gibi hizmetleri sunan, PAKSAN’ın adına ve talimatıyla çalışan firmalara aktarılır.","Mali müşavir, denetçi ve hukuk danışmanları: mevzuatın gerektirdiği ölçüde aktarılır.","Yetkili kamu kurum ve kuruluşları: mevzuatın gerektirdiği hâllerde aktarılır."]},{"baslik":"Yurt dışına aktarılıyor mu?","paragraflar":["Kişisel verileriniz şu anda yurt dışına aktarılmamaktadır. Bu durum, örneğin bildirim altyapısı nedeniyle değişirse bu metin güncellenir ve KVKK’nın 9. maddesindeki şartlara uyulur."]},{"baslik":"Nasıl toplanıyor?","paragraflar":["Verileriniz elektronik ortamda şu yollarla toplanır:"],"maddeler":["Uygulamaya yazdığınız bilgiler ve yüklediğiniz fotoğraf, video, ses kaydı ve dekontlar","Yetkili servisin sizin için açtığı kayıtlar ve makinenizde yaptığı işlemlere ilişkin kayıtlar","Telefonla PAKSAN’a ilettiğiniz bilgiler","Uygulamanın otomatik olarak oluşturduğu kayıtlar: giriş zamanları, uygulama sürümü ve bildirim izni verdiyseniz cihazınızın bildirim kimliği","Uygulama telefonunuzun konumunu kullanmaz; konum bilginiz yalnızca sizin yazdığınız il, ilçe ve adresten oluşur."]},{"baslik":"Ne kadar süre saklanıyor?","paragraflar":["Verileriniz, hesabınız açık kaldığı sürece saklanır. Hesabınız kapandıktan sonra garanti, tüketici, vergi ve ticaret mevzuatının öngördüğü süreler ile olası uyuşmazlıklara ilişkin zamanaşımı süreleri boyunca saklanır. Bu sürelerin sonunda silinir, yok edilir ya da anonim hâle getirilir."]},{"baslik":"Haklarınız neler?","paragraflar":["KVKK’nın 11. maddesi uyarınca şu haklara sahipsiniz:"],"maddeler":["Kişisel verilerinizin işlenip işlenmediğini öğrenme, işlenmişse buna ilişkin bilgi talep etme","Kişisel verilerinizin işlenme amacını ve bu amaca uygun kullanılıp kullanılmadığını öğrenme","Kişisel verilerinizin yurt içinde veya yurt dışında aktarıldığı üçüncü kişileri bilme","Kişisel verileriniz eksik veya yanlış işlenmişse düzeltilmesini isteme","Şartları oluştuğunda kişisel verilerinizin silinmesini veya yok edilmesini isteme","Düzeltme ve silme işlemlerinin, kişisel verilerinizin aktarıldığı üçüncü kişilere bildirilmesini isteme","Kişisel verilerinizin yalnızca otomatik sistemlerle analiz edilmesi sonucunda aleyhinize bir sonuç ortaya çıkmasına itiraz etme","Kişisel verilerinizin kanuna aykırı işlenmesi nedeniyle zarara uğrarsanız zararın giderilmesini talep etme"]},{"baslik":"Nasıl başvurursunuz?","paragraflar":["Başvurunuzu yukarıdaki adresimize ıslak imzalı dilekçeyle iletebilirsiniz. Ayrıca kayıtlı elektronik posta (KEP), güvenli elektronik imza veya mobil imza kullanarak ya da daha önce bize bildirdiğiniz ve sistemimizde kayıtlı olan e-posta adresinizden paksan@paksanmakina.com.tr adresine yazarak başvurabilirsiniz.","Başvurunuzda adınız ve soyadınız, T.C. kimlik numaranız (yabancıysanız uyruğunuz ve pasaport numaranız), tebligat adresiniz, varsa e-posta adresiniz ve telefon numaranız ile talebinizin konusu yer almalıdır.","Başvurunuz en geç 30 gün içinde ücretsiz olarak sonuçlandırılır. Yanıtı yeterli bulmazsanız Kişisel Verileri Koruma Kurulu’na şikâyette bulunabilirsiniz.","Hesabınızın kapatılmasını ve verilerinizin silinmesini de aynı yollarla isteyebilirsiniz. Bu işlemleri PAKSAN yapar. Yasal saklama süresine tabi kayıtlar (örneğin faturalar) bu sürenin sonuna kadar saklanır; diğer kayıtlar silinir ya da anonim hâle getirilir.","Uygulama, 18 yaşından büyük kullanıcılar içindir."]}]}', 0xB950E88D2FF052FD17ACF47D72FCCBD8F84578D01D45FC44095683DECB4E48C3, 1, N'2026-09-29'),
        (N'ticariIleti', N'1.1', N'en', N'Campaign and Announcement Notifications', N'{"kisaAd":"Campaign Notifications","onayCumlesi":"I would like to receive campaign, announcement and new product notifications through the app.","bolumler":[{"baslik":"What do we send?","paragraflar":["If you allow it, we send new product announcements, seasonal campaigns, dealer events and spare part offers to your phone as app notifications. At present SMS, e-mail or phone calls are not used for these notifications. If these channels are ever used, we will ask for your permission separately."]},{"baslik":"This permission is optional","paragraflar":["You can use the app fully without giving this permission. Machine registration, troubleshooting support, service and spare part requests work independently of it.","Service notifications such as the status of your request or safety warnings about your machine are not campaign notifications and are sent independently of this permission."]},{"baslik":"You can turn it off at any time","paragraflar":["You can turn this permission on and off on the \"Privacy and Permissions\" page in \"Profile\". The date of the last change is shown on the same page. You can also withdraw it by writing to paksan@paksanmakina.com.tr. You can turn off all of the app''s notifications in your phone''s settings as well."]}],"ustNot":"This is an English translation provided for convenience. The binding text is the Turkish original, prepared under Turkish Personal Data Protection Law No. 6698 (KVKK)."}', 0xEB29354220B706D56C7A3B51FC1C93C1A1C29C10AA6B1221F162EE9A3DC57D7D, 0, N'2026-09-29'),
        (N'ticariIleti', N'1.1', N'tr', N'Kampanya ve Duyuru Bildirimleri', N'{"kisaAd":"Kampanya Bildirimleri Metni","onayCumlesi":"Kampanya, duyuru ve yeni ürün bildirimlerinin uygulama üzerinden bana gönderilmesini istiyorum.","bolumler":[{"baslik":"Ne gönderiyoruz?","paragraflar":["İzin verirseniz yeni ürün duyurularını, sezon kampanyalarını, bayi etkinliklerini ve yedek parça fırsatlarını uygulama bildirimi olarak telefonunuza gönderiyoruz. Şu anda bu bildirimler için SMS, e-posta ya da telefon araması kullanılmıyor. Bu iletişim yolları kullanılacak olursa ayrıca izninizi isteriz."]},{"baslik":"Bu izin zorunlu değil","paragraflar":["Bu izni vermeseniz de uygulamayı eksiksiz kullanabilirsiniz. Makine kaydı, arıza desteği, servis ve yedek parça talepleri bu izinden bağımsız olarak çalışır.","Talebinizin durumu ya da makinenizle ilgili güvenlik uyarıları gibi hizmete ilişkin bildirimler, kampanya bildirimi sayılmaz ve bu izinden bağımsız olarak gönderilir."]},{"baslik":"İstediğiniz zaman kapatabilirsiniz","paragraflar":["Bu izni, \"Profil\" sayfasındaki \"Gizlilik ve İzinler\" sayfasından açıp kapatabilirsiniz. Son değişikliğin tarihi aynı sayfada görünür. İzninizi paksan@paksanmakina.com.tr adresine yazarak da geri alabilirsiniz. Telefonunuzun ayarlarından uygulamanın tüm bildirimlerini de kapatabilirsiniz."]}]}', 0x3239D114E858C95E2936356398955181ACCDA55DFBE0EEBD1ADC424C64F7C891, 1, N'2026-09-29')
    ) AS v (MetinKodu, Surum, DilKodu, Baslik, IcerikJson, IcerikOzeti, AsilMetin, MetinTarihi)
) AS k
WHERE NOT EXISTS (SELECT 1 FROM kvkk.MetinSurumu AS h WHERE h.MetinKodu = k.MetinKodu AND h.Surum = k.Surum AND h.DilKodu = k.DilKodu);
